"""Katalog yükleyici.

Tek katalog, iki yüz: pre-sales.hisarresearch.com'daki hizmet kimliği ile buradaki
`id` aynı olmak zorundadır. Farklılaşırsa satılan ile teslim edilen ayrışır.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path

import yaml

from app.models import Lane

VALID_GRADES = {"FULL", "ASSISTED", "HUMAN"}
VALID_STORES = {".env", "ansible-vault", "n8n-credentials"}


class CatalogError(Exception):
    """Katalog tutarsızlığı — açılışta patlar, çalışma anında değil."""


@dataclass(frozen=True)
class Task:
    id: str
    lane: Lane
    action: str
    description: str
    params: dict = field(default_factory=dict)
    requires_secret: list[str] = field(default_factory=list)


@dataclass(frozen=True)
class CatalogService:
    id: str
    name: str
    area: str
    tier: str
    lane: Lane
    lanes: tuple[Lane, ...]
    plain: str
    executor: str
    automation_grade: str
    secret_stores: tuple[str, ...]
    requires: tuple[str, ...]
    tasks: tuple[Task, ...]
    health_check: str
    gotcha: str
    teardown: tuple[Task, ...]

    @property
    def first_task_is_vault(self) -> bool:
        """Her hizmetin ilk adımı erişim bilgilerinin kasaya yazılmasıdır."""
        return bool(self.tasks) and self.tasks[0].action == "vault.store_access"


@dataclass
class Catalog:
    services: dict[str, CatalogService]

    def __iter__(self):
        return iter(self.services.values())

    def __len__(self) -> int:
        return len(self.services)

    def get(self, service_id: str) -> CatalogService:
        try:
            return self.services[service_id]
        except KeyError as exc:
            raise CatalogError(f"katalogda yok: {service_id}") from exc

    def by_lane(self, lane: Lane) -> list[CatalogService]:
        return [s for s in self.services.values() if s.lane is lane]


def _task(raw: dict, where: str) -> Task:
    for key in ("id", "lane", "action"):
        if key not in raw:
            raise CatalogError(f"{where}: görevde '{key}' eksik")
    return Task(
        id=raw["id"],
        lane=Lane(raw["lane"]),
        action=raw["action"],
        description=raw.get("description", ""),
        params=raw.get("params", {}) or {},
        requires_secret=list(raw.get("requires_secret", []) or []),
    )


def load_catalog(directory: str | Path) -> Catalog:
    path = Path(directory)
    if not path.is_dir():
        raise CatalogError(f"katalog klasörü yok: {path}")

    services: dict[str, CatalogService] = {}
    for file in sorted(path.glob("*.yaml")):
        raw = yaml.safe_load(file.read_text(encoding="utf-8"))
        sid = raw.get("id")
        if not sid:
            raise CatalogError(f"{file.name}: 'id' eksik")
        if sid in services:
            raise CatalogError(f"{file.name}: yinelenen kimlik {sid}")
        if raw.get("automation_grade") not in VALID_GRADES:
            raise CatalogError(f"{sid}: geçersiz automation_grade")

        stores = tuple(raw.get("secret_stores", []) or [])
        unknown = set(stores) - VALID_STORES
        if unknown:
            raise CatalogError(f"{sid}: bilinmeyen kasa {unknown}")

        tasks = tuple(_task(t, sid) for t in raw.get("tasks", []))
        service = CatalogService(
            id=sid,
            name=raw["name"],
            area=raw.get("area", ""),
            tier=raw.get("tier", "Proje"),
            lane=Lane(raw["lane"]),
            lanes=tuple(Lane(x) for x in raw.get("lanes", [raw["lane"]])),
            plain=raw.get("plain", ""),
            executor=raw.get("executor", ""),
            automation_grade=raw["automation_grade"],
            secret_stores=stores,
            requires=tuple(raw.get("requires", []) or []),
            tasks=tasks,
            health_check=raw.get("health_check", ""),
            gotcha=raw.get("gotcha", ""),
            teardown=tuple(_task(t, sid) for t in raw.get("teardown", []) or []),
        )
        if not service.first_task_is_vault:
            raise CatalogError(
                f"{sid}: ilk görev 'vault.store_access' olmalı — "
                "kasaya yazılmamış yetkiyle hizmet başlatılmaz"
            )
        services[sid] = service

    # ön koşullar katalogda var mı
    for svc in services.values():
        for dep in svc.requires:
            if dep not in services:
                raise CatalogError(f"{svc.id}: tanımsız ön koşul {dep}")
    return Catalog(services=services)

"""Görev grafiği: hizmetleri ön koşullarına göre sıralar.

Bir hizmetin görevleri, bağlı olduğu hizmetlerin görevleri bittikten sonra sıraya girer.
Böylece Zabbix host'u, türetildiği NetBox kaydından önce oluşturulamaz.
"""
from __future__ import annotations

from collections import deque

from app.catalog import Catalog, CatalogService


class DependencyCycle(Exception):
    pass


def topological_order(catalog: Catalog, service_ids: list[str]) -> list[CatalogService]:
    """Verilen hizmetleri bağımlılık sırasına dizer (kararlı: alfabetik ikincil sıra)."""
    wanted = set(service_ids)

    # kapanış: ön koşullar hak setinde olmasa bile kurulmalıdır
    queue = deque(wanted)
    while queue:
        sid = queue.popleft()
        for dep in catalog.get(sid).requires:
            if dep not in wanted:
                wanted.add(dep)
                queue.append(dep)

    indegree = {sid: 0 for sid in wanted}
    dependents: dict[str, list[str]] = {sid: [] for sid in wanted}
    for sid in wanted:
        for dep in catalog.get(sid).requires:
            indegree[sid] += 1
            dependents[dep].append(sid)

    ready = sorted([sid for sid, deg in indegree.items() if deg == 0])
    order: list[str] = []
    while ready:
        sid = ready.pop(0)
        order.append(sid)
        for nxt in sorted(dependents[sid]):
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                ready.append(nxt)
                ready.sort()

    if len(order) != len(wanted):
        stuck = sorted(set(wanted) - set(order))
        raise DependencyCycle(f"ön koşul döngüsü: {stuck}")
    return [catalog.get(sid) for sid in order]

"""Ajan kimliği ve kiracı sınırı.

Kasa, her müşterinin sırlarını tutar. Acme'nin ajanı, Contoso'nun tanımını isteyememelidir;
bu yüzden her istek cihaz kimliğine bağlı bir belirteçle imzalanır ve kiracı sunucuda çözülür.
"""
from __future__ import annotations

import hashlib
import hmac
import secrets
from datetime import datetime, timedelta, timezone

from fastapi import Header, HTTPException

from app.config import settings

TOKEN_TTL = timedelta(hours=12)


SEP = "|"  # ISO zaman damgası iki nokta içerdiği için ayraç olarak ':' kullanılamaz


def issue_agent_token(*, tenant: str, device_uuid: str) -> str:
    """Kayıt sırasında cihaza özel belirteç üretir."""
    if SEP in tenant or SEP in device_uuid:
        raise ValueError(f"kiracı veya cihaz kimliğinde ayraç karakteri: {SEP}")
    issued = datetime.now(timezone.utc).isoformat()
    body = SEP.join((tenant, device_uuid, issued))
    mac = hmac.new(settings().agent_enroll_secret.encode(), body.encode(), hashlib.sha256)
    return SEP.join((body, mac.hexdigest()))


def verify_agent_token(token: str) -> tuple[str, str]:
    """(tenant, device_uuid) döndürür; geçersizse 401."""
    try:
        tenant, device_uuid, issued, mac = token.split(SEP)
    except ValueError:
        raise HTTPException(401, "bozuk belirteç") from None

    body = SEP.join((tenant, device_uuid, issued))
    expected = hmac.new(
        settings().agent_enroll_secret.encode(), body.encode(), hashlib.sha256
    ).hexdigest()
    if not hmac.compare_digest(mac, expected):
        raise HTTPException(401, "imza doğrulanamadı")
    if datetime.fromisoformat(issued) + TOKEN_TTL < datetime.now(timezone.utc):
        raise HTTPException(401, "belirteç süresi doldu")
    return tenant, device_uuid


async def agent_identity(authorization: str = Header(default="")) -> tuple[str, str]:
    if not authorization.startswith("Bearer "):
        raise HTTPException(401, "yetki başlığı yok")
    return verify_agent_token(authorization.removeprefix("Bearer ").strip())


def new_enrollment_code() -> str:
    return secrets.token_urlsafe(24)

"""Zabbix — izleme. D şeridinin ana yükü buradadır.

Ajanın kurulması taşımadır; satılan şey host kaydı, şablon bağı ve uyarı kuralıdır.
A şeridi kusursuz çalışıp D şeridi hiç koşmazsa müşteri hiçbir şey satın almamış olur.
"""
from __future__ import annotations

from app.config import settings
from app.integrations._client import request


async def _rpc(method: str, params: dict) -> dict:
    return await request(
        "POST", settings().zabbix_url,
        json={"jsonrpc": "2.0", "method": method, "params": params, "id": 1},
        headers={"Authorization": f"Bearer {settings().zabbix_token}"},
    )


async def call(op: str, *, tenant: str, **params) -> dict:
    return await {
        "ensure_host_group": ensure_host_group,
        "ensure_host": ensure_host,
        "link_template": link_template,
        "ensure_action": ensure_action,
    }[op](tenant=tenant, **params)


async def ensure_host_group(*, tenant: str, **_) -> dict:
    return await _rpc("hostgroup.create", {"name": f"tenant/{tenant}"})


async def ensure_host(*, tenant: str, host: str, proxy: str | None = None, **_) -> dict:
    """Host her zaman müşterinin site relay proxy'sine bağlanır — doğrudan değil."""
    return await _rpc(
        "host.create",
        {
            "host": host,
            "groups": [{"name": f"tenant/{tenant}"}],
            "proxy_hostid": proxy or f"relay-{tenant}",
            "tags": [{"tag": "tenant", "value": tenant}],
        },
    )


async def link_template(*, tenant: str, host: str, template: str, **_) -> dict:
    return await _rpc("host.update", {"host": host, "templates": [{"name": template}]})


async def ensure_action(*, tenant: str, name: str, escalation: list | None = None, **_) -> dict:
    return await _rpc(
        "action.create",
        {"name": f"{tenant}/{name}", "operations": escalation or [], "status": 0},
    )

