    return {
        "spec": spec.to_json(),
        "summary": {
            "services": len(spec.services),
            "tasks": len(spec.tasks),
            "removed": spec.removed,
            "by_lane": {
                lane: len([t for t in spec.tasks if t.lane == lane]) for lane in "ABCDEF"
