"""Relay API — ajanların tek muhatabı.

Ajan platformu doğrudan görmez; her şey relay üzerinden geçer. Bu, müşteri ağından
dışarı tek bir çıkış noktası olmasını sağlar.
"""
from __future__ import annotations

import os

import structlog
from fastapi import FastAPI, Header, HTTPException
from pydantic import BaseModel

import jobqueue  # stdlib 'queue' ile çakışmaması için bilerek bu ad

log = structlog.get_logger(__name__)
app = FastAPI(title="Hisar Site Relay", version="0.1.0")

TENANT = os.environ.get("RELAY_TENANT", "")
RELAY_TOKEN = os.environ.get("RELAY_TOKEN", "")


class Task(BaseModel):
    service_id: str
    task_id: str
    action: str
    params: dict = {}
    device_uuid: str | None = None
    teardown: bool = False


class Checkin(BaseModel):
    device_uuid: str
    observed: dict = {}
    inventory: dict = {}


def _require_platform(authorization: str) -> None:
    if not RELAY_TOKEN or authorization != f"Bearer {RELAY_TOKEN}":
        raise HTTPException(401, "yetkisiz")


@app.get("/healthz")
async def healthz() -> dict:
    return {"status": "ok", "tenant": TENANT, "queue_depth": await jobqueue.depth(TENANT)}


@app.post("/queue")
async def enqueue(task: Task, authorization: str = Header(default="")) -> dict:
    """Platform görev bırakır."""
    _require_platform(authorization)
    return await jobqueue.push(TENANT, task.model_dump())


@app.post("/agents/checkin")
async def checkin(req: Checkin) -> dict:
    """Ajan yoklaması: durumunu bildirir, bekleyen görevlerini alır."""
    tasks = await jobqueue.pop_all(TENANT, req.device_uuid)
    log.info("ajan_yoklamasi", cihaz=req.device_uuid, gorev=len(tasks))
    return {"tasks": tasks, "next_checkin": int(os.environ.get("CHECKIN_SECONDS", "45"))}

"""Görev yürütücü: platformdan gelen eylemi uygun uygulayıcıya bağlar."""
from __future__ import annotations

import structlog

from hragent.apply import ensure_file, ensure_package, ensure_service

log = structlog.get_logger(__name__)


class UnknownAction(Exception):
    pass


def run_task(task: dict, *, dry_run: bool = False) -> dict:
    """Tek bir görevi uygular ve sonucu döndürür. İstisna yutulmaz, yukarı taşınır."""
    action = task.get("action", "")
    params = task.get("params", {}) or {}
    key = f"{task.get('service_id')}/{task.get('task_id')}"

    if action != "agent.converge":
        raise UnknownAction(f"{key}: ajan bu eylemi yürütmez → {action}")

    results = []
    for pkg in params.get("packages", []):
        results.append(ensure_package(pkg["name"], version=pkg.get("version"), dry_run=dry_run))
    for svc in params.get("services", []):
        results.append(ensure_service(svc["name"], state=svc.get("state", "running"),
                                      dry_run=dry_run))
    for f in params.get("files", []):
        results.append(ensure_file(f["path"], f["content"], mode=int(f.get("mode", "644"), 8),
                                   secret=f.get("secret", False), dry_run=dry_run))

    failed = [r for r in results if r["state"] == "failed"]
    return {
        "key": key,
        "state": "failed" if failed else "ok",
        "changed": any(r["changed"] for r in results),
        "details": results,
    }

"""Sır okuma.

Ajanın çalıştırdığı hiçbir script parolayı içinde taşımaz. Değerler `.env` dosyasından
okunur; dosya 0600 izinleriyle durur ve depoya asla girmez.
"""
from __future__ import annotations

import os
import stat
from pathlib import Path

import structlog

log = structlog.get_logger(__name__)

DEFAULT_PATHS = (
    Path("/etc/hragent/.env"),
    Path("C:/ProgramData/HRAgent/.env"),
    Path(".env"),
)


class InsecureSecretFile(Exception):
    """Sır dosyası fazla açık izinlerle duruyorsa okumayı reddederiz."""


def _check_permissions(path: Path) -> None:
    if os.name == "nt":  # Windows'ta izin modeli farklı, ACL ayrıca kontrol edilir
        return
    mode = path.stat().st_mode
    if mode & (stat.S_IRGRP | stat.S_IROTH):
        raise InsecureSecretFile(f"{path}: grup/diğer okuyabiliyor, 0600 olmalı")


def load(path: str | None = None) -> dict:
    """`.env` dosyasını okur. Değerler süreç dışına hiç çıkmaz."""
    candidates = [Path(path)] if path else list(DEFAULT_PATHS)
    for candidate in candidates:
        if not candidate.is_file():
            continue
        _check_permissions(candidate)
        values = {}
        for line in candidate.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            key, _, value = line.partition("=")
            values[key.strip()] = value.strip().strip('"').strip("'")
        log.info("sirlar_yuklendi", kaynak=str(candidate), anahtar_sayisi=len(values))
        return values
    log.warning("sir_dosyasi_bulunamadi", aranan=[str(c) for c in candidates])
    return {}


def get(key: str, default: str = "") -> str:
    """Önce ortam değişkeni, sonra `.env`. Koda gömülü varsayılan parola yoktur."""
    if key in os.environ:
        return os.environ[key]
    return load().get(key, default)

"""Paket kurulumu. Paketler site relay'in önbelleğinden çekilir — geniş alan ağı doymasın."""
from __future__ import annotations

import platform
import subprocess

import structlog

log = structlog.get_logger(__name__)

MANAGERS = {
    "Windows": ["winget", "install", "--silent", "--accept-package-agreements", "--id"],
    "Linux": ["apt-get", "install", "-y"],
    "Darwin": ["brew", "install"],
}


class UnsupportedPlatform(Exception):
    pass


def _installed(name: str) -> bool:
    system = platform.system()
    probe = {
        "Windows": ["winget", "list", "--id", name],
        "Linux": ["dpkg", "-s", name],
        "Darwin": ["brew", "list", name],
    }.get(system)
    if not probe:
        raise UnsupportedPlatform(system)
    return subprocess.run(probe, capture_output=True, check=False).returncode == 0


def ensure_package(name: str, *, version: str | None = None, dry_run: bool = False) -> dict:
    """İstenen paketin kurulu olmasını sağlar. Kurulu ise hiçbir şey yapmaz."""
    if _installed(name):
        return {"action": "package", "name": name, "state": "ok", "changed": False}
    if dry_run:
        return {"action": "package", "name": name, "state": "would-install", "changed": False}

    system = platform.system()
    cmd = MANAGERS.get(system)
    if not cmd:
        raise UnsupportedPlatform(system)
    target = f"{name}={version}" if version and system == "Linux" else name
    result = subprocess.run([*cmd, target], capture_output=True, text=True, check=False)
    ok = result.returncode == 0
    if not ok:
        log.error("paket_kurulamadi", paket=name, kod=result.returncode, hata=result.stderr[:400])
    return {
        "action": "package", "name": name,
        "state": "ok" if ok else "failed",
        "changed": ok, "exit_code": result.returncode,
    }

"""Dosya içeriği ve izinleri. Sır dosyaları daima 0600 yazılır."""
from __future__ import annotations

import hashlib
import os
from pathlib import Path

SECRET_MODE = 0o600


def _digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def ensure_file(
    path: str, content: str, *, mode: int = 0o644, secret: bool = False, dry_run: bool = False
) -> dict:
    target = Path(path)
    desired = content.encode("utf-8")
    effective_mode = SECRET_MODE if secret else mode

    if target.is_file() and _digest(target.read_bytes()) == _digest(desired):
        if os.name != "nt" and (target.stat().st_mode & 0o777) != effective_mode:
            if not dry_run:
                target.chmod(effective_mode)
            return {"action": "file", "path": path, "state": "ok", "changed": True}
        return {"action": "file", "path": path, "state": "ok", "changed": False}

    if dry_run:
        return {"action": "file", "path": path, "state": "would-write", "changed": False}

    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(desired)
    if os.name != "nt":
        target.chmod(effective_mode)
    return {"action": "file", "path": path, "state": "ok", "changed": True}

